using System.Collections.Generic;

namespace PlantsPlus.Core
{
    internal static class PlantFlavorText
    {
        private static readonly Dictionary<string, (string En, string Fr, string Zh)> Texts = new()
        {
            ["Lotus Pumpkin"] = ("Lotus Pumpkin keeps a box of old buttons under her leaf. None of them match, but she can tell you who gave her every single one. She sews them onto the patches in her shell. \"This blue one's from Wall-nut. Lovely fellow. Terrible with needles.\" She'll mend your coat, too, if you can sit still.",
                "Citrouille Lotus garde une boîte de vieux boutons sous sa feuille. Aucun ne va avec les autres, mais elle se souvient de qui lui a donné chacun d'eux. Elle les coud sur les pièces de sa coque. « Le bleu, c'est Noix. Un amour. Pas doué avec une aiguille, par contre. » Elle peut aussi raccommoder votre manteau, si vous arrêtez de gigoter.",
                "莲花南瓜在叶子下收着一盒旧纽扣。没有两颗配得上，她却记得每一颗是谁送的。她把它们缝在壳上的补丁上。“蓝色这颗是坚果给的。好心肠，就是不会用针。”只要你别乱动，她也愿意帮你补外套。"),
            ["Bambnut"] = ("Bambnut loves detective novels. Before opening one, he turns to the last page to make sure the culprit gets caught. Then he reads it properly and gasps at every clue. \"I knew it!\" he says. He's particularly pleased when the detective agrees with him.",
                "Bamb-noix adore les romans policiers. Avant d'en commencer un, il lit la dernière page pour vérifier qu'on attrape bien le coupable. Ensuite, il reprend au début et s'étonne à chaque indice. « Je le savais ! » s'exclame-t-il. Il est particulièrement content quand le détective arrive à la même conclusion que lui.",
                "竹坚果爱看侦探小说。翻开书之前，他先看最后一页，确认坏人被抓住了。然后从头认真读，每发现一条线索都很激动：“我就知道！”侦探得出和他相同的结论时，他尤其满意。"),
            ["Iceberg-shroom"] = ("Every spring, Iceberg-shroom receives the same letter: please make room for the flowers. He reads it carefully, files it away and turns over in his sleep. There's a whole drawer of them under the snow.",
                "Chaque printemps, Champi-iceberg reçoit la même lettre : merci de laisser un peu de place aux fleurs. Il la lit attentivement, la range, puis se retourne dans son sommeil. Il en a tout un tiroir sous la neige.",
                "每到春天，冰山菇都会收到同一封信：请给花留点地方。他认真读完，收好，然后翻个身继续睡。雪下面已经攒满一抽屉了。"),
            ["Witchfire Pumpkin"] = ("Witchfire Pumpkin set an extra place at dinner. Nobody could remember who it was for. Then the candle went out, the empty chair scraped across the floor, and she asked everyone to pass the salt.",
                "Citrouille Sorcière a mis un couvert de plus pour le dîner. Personne ne se rappelait qui devait venir. Puis la chandelle s'est éteinte, la chaise vide a raclé le sol, et elle a simplement demandé qu'on lui passe le sel.",
                "巫火南瓜在餐桌上多摆了一副碗筷。谁也不记得还有哪位客人。随后蜡烛灭了，空椅子在地板上拖出一声响。她只是请大家把盐递过来。"),
            ["Nutty Sharpshooter"] = ("Nutty Sharpshooter used to spend an hour choosing a scarf before going out. These days he puts on his shell and he's ready. He's very happy with the arrangement. His scarves aren't. He still buys them, folds them carefully, and promises each one its turn will come.",
                "Épicéa Blindé passait une heure à choisir son écharpe avant de sortir. Maintenant, il enfile sa coque et le voilà prêt. Il est ravi du changement. Ses écharpes, beaucoup moins. Il continue à en acheter, les plie soigneusement et promet à chacune que son tour viendra.",
                "坚果神射手以前出门要花一小时挑围巾。如今套上壳就行，他很满意。围巾们可不满意。他仍然买新的，叠得整整齐齐，再向每一条保证：总有一天会轮到你。"),
            ["Inferno Torchflower"] = ("\"It's not hoarding. It's a holiday fund.\" Inferno Torchflower has been saving for the seaside for years. She's picked the hotel, the beach and the sun hat. All that's left is to pay the deposit. Every time she reaches for her savings, she remembers the beach will still be there next summer.",
                "« Ce n'est pas de l'avarice. C'est pour les vacances. » Tournesol Infernal économise depuis des années pour aller à la mer. Elle a choisi l'hôtel, la plage et le chapeau. Il ne reste qu'à verser l'acompte. Chaque fois qu'elle ouvre sa réserve, elle se rappelle que la plage sera encore là l'été prochain.",
                "“这不叫小气，是攒钱度假。”炼狱火炬花为了去海边已经攒了好几年。旅馆、沙滩和帽子都挑好了，只差付定金。可每次打开存款，她就想：沙滩明年夏天也还在嘛。"),
            ["Pumpkin Podbomber"] = ("Pumpkin Podbomber is an excellent listener. She lets you finish, nods at the right places and remembers every word. A little too well, sometimes. Peashooter is still trying to explain that \"I'm going to lose my temper\" wasn't a firing order.",
                "Citrouille Grenadière sait écouter. Elle vous laisse finir, hoche la tête au bon moment et retient chaque mot. Parfois un peu trop bien. Pisto-pois essaie encore de lui expliquer que « je vais exploser » n'était pas un ordre de tir.",
                "南瓜荚轰炸手很会听人说话。她不打断，会适时点头，每句话都记得清楚。有时候清楚过头了。豌豆射手还在向她解释，“我要气炸了”真的不是开火命令。"),
            ["Cherry StarBomber"] = ("Cherry StarBomber follows the horoscopes in three different newspapers. She takes the best prediction from each and crosses out the rest. \"Lucky in love, successful at work, excellent health. See? They all agree.\" The explosions, she says, are a separate matter.",
                "Carambombe lit l'horoscope dans trois journaux différents. Elle garde la meilleure prédiction de chacun et raye le reste. « Bonheur en amour, réussite au travail, santé de fer. Tu vois ? Ils sont tous d'accord. » Les explosions, selon elle, c'est un autre sujet.",
                "樱桃星爆手每天看三份报纸的星座运势。每份只留最好的一条，其他全划掉。“爱情顺利，事业成功，身体健康。看，他们意见一致！”至于爆炸，她说那是另一回事。"),
            ["Not-a-pea"] = ("\"I'm not angry. That's just how my teeth look.\" Not-a-pea is tired of explaining this. He practises smiling in the bathroom mirror before parties, trying not to show quite so many teeth. He's getting better. Last week, someone stayed long enough to ask his name.",
                "« Je ne suis pas en colère. C'est juste mes dents. » Pisto-scie en a assez de devoir l'expliquer. Avant les fêtes, il s'entraîne à sourire devant la glace en essayant d'en montrer un peu moins. Il fait des progrès. La semaine dernière, quelqu'un est resté assez longtemps pour lui demander son nom.",
                "“我没生气，我的牙就长这样。”锯齿豌豆已经解释累了。参加聚会前，他会对着镜子练习微笑，尽量少露几颗牙。最近有进步。上星期，总算有人待到问出他的名字。"),
            ["Not-a-storm Commando"] = ("Commando likes quiet afternoons, model ships and camomile tea. He paints every tiny window on every tiny deck. \"Steady hands,\" he says. \"That's the secret.\" There's a note on his door asking visitors to knock gently. The last surprise visit set the battleship project back six months.",
                "Commando Scieur aime les après-midi tranquilles, les maquettes de bateaux et la camomille. Il peint une à une les minuscules fenêtres de chaque pont. « Une main sûre. Tout est là. » Un mot sur sa porte demande de frapper doucement. La dernière visite surprise lui a coûté six mois de travail sur son cuirassé.",
                "锯齿风暴突击手喜欢安静的下午、舰船模型和洋甘菊茶。他会一扇一扇画好甲板上的小窗。“手要稳，秘诀就在这里。”门上贴着“请轻轻敲门”。上次有人突然来访，他的战列舰模型得重做半年。"),
            ["Frost Furflower"] = ("Frost Furflower has kept the carrot from her first snowman. Every winter she builds him again, in the same corner, with the same crooked smile. The others offer to find a better carrot. She won't hear of it. \"He's always looked like that. He'd be upset if we changed it.\"",
                "Tournesol Givré a gardé la carotte de son premier bonhomme de neige. Chaque hiver, elle le refait au même coin du jardin, avec le même sourire de travers. Les autres proposent de lui trouver une plus jolie carotte. Pas question. « Il a toujours eu cette tête-là. Ça lui ferait de la peine qu'on la change. »",
                "霜绒花一直留着第一个雪人的胡萝卜。每年冬天，她都在花园同一个角落把他堆回来，连歪歪的笑脸都不变。大家想帮她换根好看的胡萝卜，她坚决不肯。“他一直长这样。换了，他会难过的。”"),
            ["Doomtronion"] = ("Doomtronion remembers being small enough to fit under a leaf. He remembers the rain against it, too. Everything after that is harder to put in order. Sometimes, when the garden is asleep, he asks the old trees whether they remember him. He waits until morning for an answer.",
                "Amp-mort se souvient qu'il tenait autrefois sous une feuille. Il se souvient aussi du bruit de la pluie dessus. Le reste est plus difficile à remettre dans l'ordre. Parfois, quand le jardin dort, il demande aux vieux arbres s'ils se rappellent de lui. Il attend leur réponse jusqu'au matin.",
                "毁灭电洋葱记得，自己曾经小到可以躲在一片叶子下面。他还记得雨打在叶子上的声音。后来的事，就很难排清先后了。有时花园睡着后，他会问老树还记不记得自己，然后等到天亮。"),
            ["Lichen-pea"] = ("Lichen-pea is knitting a scarf. The pattern is simple, but the wool keeps freezing to the needles. Firnace offered to hold it for him. That didn't work either. They've spent three evenings together over a single row, drinking tea and arguing about whose fault it is. Neither seems in a hurry to finish.",
                "Pisto-lichen tricote une écharpe. Le modèle est simple, mais la laine gèle sur les aiguilles. Four Polaire a proposé de la tenir pour lui. Ça n'a pas marché non plus. Ils passent leur troisième soirée sur le même rang, à boire du thé et à se renvoyer la faute. Aucun des deux n'a l'air pressé de finir.",
                "地衣豌豆正在织围巾。花样不难，就是毛线总冻在针上。小松炉提议帮他拿着，结果也不太行。两位已经对着同一排针脚坐了三个晚上，喝着茶，争论是谁的问题。谁都不着急织完。"),
            ["Logic Blover"] = ("\"Left or right?\" Logic Blover asks before a walk. He checks the wind, the distance and the odds of meeting someone he knows. By the time he's decided, it's dark. He's calculated that staying home was the better option anyway. Tomorrow he'll account for the time spent calculating.",
                "« À gauche ou à droite ? » Troufle Logique consulte le vent, la distance et la probabilité de croiser une connaissance avant de sortir. Quand il a choisi, il fait nuit. D'après ses calculs, rester chez lui était de toute façon préférable. Demain, il prendra aussi en compte le temps passé à calculer.",
                "“往左还是往右？”出门前，逻辑三叶草要算风向、距离，以及遇到熟人的概率。等他决定好，天已经黑了。计算表明，留在家里本来就是更好的选择。明天，他打算把计算耗时也算进去。"),
            ["Solar Sharpshooter"] = ("Solar Sharpshooter gives generously to the garden's picnic fund. He also checks every receipt, counts every spoon and asks what happened to last year's napkins. \"Generosity doesn't mean we can't keep things tidy.\" He's brought his own sandwich. It's on the spreadsheet.",
                "Epicéa Tireur Solaire contribue généreusement aux pique-niques du jardin. Il vérifie aussi chaque ticket, recompte les cuillères et demande ce qu'on a fait des serviettes de l'an dernier. « Être généreux n'empêche pas de bien tenir les comptes. » Il a apporté son propre sandwich. Il figure dans le tableau.",
                "太阳神射手给花园野餐捐钱很大方。他也会检查每张收据、数清每把勺子，再问去年的纸巾用到哪儿了。“大方和记账不冲突。”他的三明治是自己带的，表格里也记着。"),
            ["Sea Ballista"] = ("Sea Ballista keeps a bell from an old ship beside her. Every evening, she rings it once and waits. Some nights, another bell answers from farther out. She won't say which ship she's expecting.",
                "Baliste Marine garde près d'elle la cloche d'un vieux navire. Chaque soir, elle la fait sonner une fois, puis attend. Certaines nuits, une autre cloche lui répond au large. Elle ne dit jamais quel bateau elle attend.",
                "海上弩炮身边放着一口旧船钟。每晚她敲一下，然后等待。有些夜里，远处海面会传来另一声钟响。她不肯说在等哪艘船。"),
            ["Sea Sharpshooter"] = ("He asks passing Sea-shrooms what the sky looks like. Blue, they say. Just like down here, then? Not quite. He grows a little taller after every answer. One day, he'd like to see the difference himself.",
                "Epicéa Tireur des Mers demande aux Champi-mers de passage à quoi ressemble le ciel. Bleu, lui répondent-ils. Comme ici, alors ? Pas tout à fait. Après chaque réponse, il pousse un peu plus haut. Un jour, il aimerait voir la différence lui-même.",
                "海洋神射手问路过的海蘑菇，天空是什么样。“蓝色。”那不就和这里一样？“不太一样。”每听一次回答，他就再长高一点。总有一天，他想亲眼看看。"),
            ["Three-Buckpeater"] = ("The left head likes detective films. The right head likes musicals. The middle head has the remote, but he likes them both. They've reached a compromise: half an hour of each. So far, the murderer has sung twice and the bride has been arrested. All three are quite enjoying it.",
                "La tête de gauche aime les films policiers. Celle de droite, les comédies musicales. Celle du milieu a la télécommande, mais elle aime les deux. Elles ont trouvé un compromis : une demi-heure de chaque. Pour l'instant, le meurtrier a chanté deux fois et la mariée s'est fait arrêter. Les trois passent une excellente soirée.",
                "左边的脑袋爱看侦探片，右边爱看歌舞片。中间拿着遥控器，两种都喜欢。他们商量好，每种看半小时。目前凶手唱了两首歌，新娘被逮捕了。三个脑袋都看得很开心。"),
            ["Pineshooter"] = ("Pineshooter is very particular about Christmas decorations. Red ornaments go on the left, gold on the right, and the star must be straight. He can spot a crooked one from the far side of the lawn. He'll fix it himself if you let him. Please take the decorations off before the next wave.",
                "Pisto-sapin est très exigeant sur les décorations de Noël. Boules rouges à gauche, dorées à droite, et l'étoile bien droite. Il repère celle qui penche depuis l'autre bout de la pelouse. Il viendra la remettre lui-même, si vous le laissez faire. Pensez juste à tout décrocher avant la prochaine vague.",
                "松树射手对圣诞装饰很讲究。红球挂左边，金球挂右边，星星一定要正。他在草坪另一头都能看出哪颗歪了。只要你肯，他会亲自来扶正。下一波僵尸到来前，记得把装饰都摘下来。"),
            ["Icytronion"] = ("Icytronion likes thunderstorms. He switches off the radio, makes a cup of tea and listens from the window. The others close the curtains when lightning flashes. He leans closer. Once he recognised a tune in the thunder. He's been waiting for the second verse ever since.",
                "Amp-glace aime les orages. Il éteint la radio, prépare son thé et écoute à la fenêtre. Les autres tirent les rideaux au premier éclair. Lui se rapproche. Une fois, il a reconnu un air dans le tonnerre. Depuis, il attend le deuxième couplet.",
                "寒冰电洋葱喜欢雷雨天。他关掉收音机，泡好茶，坐在窗前听。别人看见闪电就拉窗帘，他反而凑近。有一次，他从雷声里听出了一段曲子。从那以后，他一直在等第二段。"),
            ["Sakura Sharpshooter"] = ("Sakura Sharpshooter presses fallen petals between the pages of his diary. He dates each one and notes who was there that day. Spring, he says, is too short to trust to memory. Nobody borrows the diary anymore. Not since a pressed flower fell out during a particularly lively argument.",
                "Sakura Tireur d'Explosif conserve ses pétales entre les pages de son journal. Il note la date et qui était là ce jour-là. Le printemps est trop court, dit-il, pour se fier à sa mémoire. Plus personne ne lui emprunte le journal depuis qu'une fleur séchée en est tombée au milieu d'une discussion un peu vive.",
                "樱花神射手把落下的花瓣夹进日记，每一片都写上日期，还有当天陪着他的人。他说，春天太短，不能只靠记性。有次争论得正热闹，一朵压花从书里掉了出来。从那以后，没人再借他的日记。"),
            ["Boreal Orchid"] = ("Boreal Orchid knows everyone on the night shift by name, including the mushrooms who insist they've only stopped by. She sets out an extra cup for each of them. She doesn't ask them to stay. But when dawn comes, there are always more cups to wash than she remembers putting out.",
                "Orchidée Boréale connaît tous les habitués de la nuit par leur nom, même les champignons qui jurent qu'ils ne font que passer. Elle prépare une tasse de plus pour chacun. Elle ne leur demande pas de rester. Pourtant, à l'aube, il y a toujours davantage de tasses à laver qu'elle ne se rappelle en avoir sorti.",
                "极光兰记得每个值夜班伙伴的名字，连那些坚持说“只是路过”的蘑菇也不例外。她为他们各备一杯茶，从不开口挽留。可到了天亮，要洗的杯子总比她记得拿出来的多。"),
            ["Bounce-shroom"] = ("Bounce-shroom has tried meditation, warm milk and counting sheep. The sheep were the problem. Every time one jumped the fence, he jumped too. \"BOING! Sorry.\" He's back on warm milk.",
                "Champi-bond a essayé la méditation, le lait chaud et de compter les moutons. Les moutons, c'était le problème. À chaque saut par-dessus la barrière, il sautait aussi. « BOÏNG ! Pardon. » Il est revenu au lait chaud.",
                "弹弹菇试过冥想、热牛奶和数羊。问题出在羊身上。每有一只跳过栅栏，他也跟着跳。“嘣！抱歉。”现在又改喝热牛奶了。"),
            ["Superaqua-shroom"] = ("Superaqua-shroom still visits the same hairdresser as Aqua Sword-shroom. He asks for something \"restrained, dignified, suitable for a teacher.\" Then he spends twenty minutes choosing the fringe. Super Sharpshooter says appearances don't matter. He's never seen the appointment book.",
                "Super Champi-sabre d'Eau va toujours chez le même coiffeur que Champi-sabre d'Eau. Il demande une coupe « sobre, digne, qui convienne à un professeur ». Puis il hésite vingt minutes sur la frange. Épicéa Tireur d'Exception trouve que l'apparence n'a aucune importance. Il n'a jamais vu le carnet de rendez-vous.",
                "超级水刃菇仍和水刃菇去同一家理发店。他要求“朴素、稳重，要有老师的样子”，然后花二十分钟挑刘海。超级云杉说外表不重要。他没看过那本预约簿。"),
            ["Pulse-shroom"] = ("\"Too loud? I can turn it down.\" Pulse-shroom means it. He has a whole collection of soft songs for the end of the evening. The trouble is, Bounce-shroom always joins in on drums. They've agreed he'll only use the small cymbal after midnight. Someone should probably tell him.",
                "« Trop fort ? Je peux baisser. » Champi-pulse est sincère. Il a toute une collection de morceaux doux pour la fin de soirée. Le problème, c'est que Champi-bond l'accompagne toujours à la batterie. Ils ont convenu de n'utiliser que la petite cymbale après minuit. Il faudrait peut-être prévenir Champi-bond.",
                "“太响了？我可以小声一点。”脉冲菇是认真的，他存了好多适合夜深时放的轻柔曲子。问题是弹弹菇总要来伴奏。他们说好午夜后只敲小镲。也许该有人把这件事告诉弹弹菇。"),
            ["Bomber Drone"] = ("Bomber Drone collects postcards from places he's flown over. He could visit them properly, of course. Land, look around, try the local food. He just hasn't worked up the nerve. \"What if they ask me to take my shoes off?\" he says, looking down at the spot where feet ought to be.",
                "Drone Bombardeur collectionne les cartes postales des endroits qu'il survole. Il pourrait les visiter pour de bon : se poser, flâner, goûter la cuisine du coin. Il n'ose pas encore. « Et s'ils me demandent d'enlever mes chaussures ? » dit-il en regardant là où il devrait avoir des pieds.",
                "樱桃轰炸无人机收集自己飞过的地方的明信片。其实他可以降落，逛逛街，尝尝当地菜，可他还没鼓起勇气。“万一人家叫我脱鞋呢？”他低头看看本该长脚的地方。"),
            ["Frostbite Drone"] = ("Frostbite Drone volunteers to run the little ice-cream cart on Sundays. He remembers everyone's favourite flavour. Children get an extra scoop; he pays for it himself. He does wish they'd stop asking for cherry. Bomber Drone is very proud of helping, and the scoop hasn't cooled down yet.",
                "Drone Givré tient bénévolement le chariot à glaces le dimanche. Il connaît le parfum préféré de chacun. Les enfants ont droit à une boule de plus ; il la paie de sa poche. Il aimerait juste qu'on arrête de demander cerise. Drone Bombardeur est très fier d'avoir aidé, et la cuillère n'a pas encore refroidi.",
                "冰霜无人机每周日义务照看冰淇淋车。他记得每个人喜欢的口味，孩子们还能多得一球，由他付钱。他只希望大家别再点樱桃味。樱桃轰炸无人机很自豪能来帮忙，那把勺子到现在还没凉。"),
            ["Ice-Lord Cactus"] = ("The crown was a gift. Ice-Lord Cactus accepted it awkwardly, thanked everyone twice and asked whether he had to make a speech. He still wears it on patrol. He'd take it off, but Wall-nut spent all winter making it. When nobody's looking, he straightens it in the reflection of the ice.",
                "La couronne était un cadeau. Cactus Rois du Givre l'a acceptée, un peu gêné, a remercié tout le monde deux fois et demandé s'il fallait faire un discours. Il la porte encore pendant ses rondes. Il l'enlèverait bien, mais Noix a passé l'hiver à la fabriquer. Quand personne ne regarde, il la redresse dans le reflet de la glace.",
                "王冠是大家送的礼物。冰王仙人掌有些不好意思，谢了两遍，又问需不需要讲话。他巡逻时仍戴着。其实想摘，可坚果做了整整一个冬天。没人看见时，他会对着冰面里的倒影把王冠扶正。"),
            ["Scovilia Pepper"] = ("The gardener asked for a mild pepper. Scovilia Pepper handed him a packet labelled MILD. The label caught fire before he could read the ingredients. \"You should see the spicy one,\" she said, reaching for a welding mask.",
                "Le jardinier avait demandé un piment doux. Piment Scovilia lui a tendu un sachet marqué DOUX. L'étiquette a pris feu avant qu'il puisse lire les ingrédients. « Vous devriez voir le fort », a-t-elle ajouté en attrapant un masque de soudeur.",
                "园丁要一个不辣的。斯科维尔辣椒递给他一袋写着“微辣”的东西。配料还没看清，标签就烧了。“辣的那种更有意思。”她说着拿起了焊工面罩。"),
            ["Atomray-shroom"] = ("He covered every mirror in his room after the reflection blinked first. The next morning, one cover had fallen away. The reflection was smiling. He wasn't. He now sleeps facing the wall.",
                "Champi-rayon a couvert tous les miroirs de sa chambre après avoir vu son reflet cligner des yeux en premier. Le lendemain, un drap était tombé. Le reflet souriait. Pas lui. Depuis, il dort tourné vers le mur.",
                "倒影先眨眼之后，原子射线菇把房里所有镜子都盖上了。第二天，一块布掉了。倒影在笑，他没有。现在他睡觉时面朝墙。"),
            ["Cherry Cabbage"] = ("Cherry Cabbage has been rehearsing a love song for weeks. He knows all the words. The tune is coming along nicely. All he needs now is to get past the first line without blushing. He's told the band to stand well back, just in case. They think he's being shy. He is, but that's not the reason.",
                "Chou Cerise répète une chanson d'amour depuis des semaines. Il connaît les paroles, la mélodie commence à venir. Il ne lui reste qu'à passer la première phrase sans rougir. Il a demandé aux musiciens de se tenir loin, au cas où. Ils croient qu'il est timide. Il l'est, mais ce n'est pas pour ça.",
                "樱桃卷心菜练一首情歌练了好几周。词背熟了，调也顺了，现在只差唱第一句时别脸红。他让乐队站远些，以防万一。大家觉得他害羞。他确实害羞，但让大家站远不是因为这个。"),
            ["Lob-shroom"] = ("\"It's all in the wrist,\" Lob-shroom explains. He doesn't have wrists, but he's heard the phrase often enough to trust it. He's joined the garden's bowling club and brings his own basket. They let him play outdoors now. He's delighted: finally, a lane without a ceiling.",
                "« Tout est dans le poignet », explique Champi-lob. Il n'a pas de poignets, mais il a entendu la phrase assez souvent pour y croire. Il s'est inscrit au club de bowling du jardin et apporte son panier. Maintenant, on le fait jouer dehors. Il est ravi : enfin une piste sans plafond.",
                "“全靠手腕。”抛孢菇解释。他没有手腕，但这句话听过太多次，肯定有道理。他加入了花园保龄球俱乐部，每次都带自己的篮子。如今大家让他在室外打。他高兴极了：终于有一条没天花板的球道。"),
            ["Bumping-shroom"] = ("\"We're perfectly coordinated,\" says the top mushroom. \"Mostly,\" says the middle one. The bottom one would like to speak, but his mouth is full of dirt. They practise together every morning, arguing about the count-in. One-two-three, or three-two-one? It's important. They've scheduled another meeting.",
                "« On est parfaitement coordonnés », dit le champignon du haut. « À peu près », précise celui du milieu. Celui du bas voudrait donner son avis, mais il a de la terre dans la bouche. Champi-secousse s'entraîne tous les matins. Un-deux-trois ou trois-deux-un ? C'est important. Une autre réunion est prévue.",
                "“我们配合得天衣无缝。”上面的蘑菇说。“差不多吧。”中间的补充。下面的也想发言，可嘴里全是土。弹射孢菇每天早晨都练习，还没商量好口令喊一二三还是三二一。这个问题很重要，得再开一次会。"),
            ["Spark-shroom"] = ("Spark-shroom has a little model railway. He paints the stations, checks the timetable and waves at every train. Everything runs beautifully. Except when he gets excited. Then the express does six laps before breakfast and the passengers have to be picked out of the curtains.",
                "Champi-éclaire a un petit train miniature. Il peint les gares, vérifie les horaires et fait signe à chaque passage. Tout marche à merveille. Sauf quand il s'enthousiasme. Là, l'express fait six tours avant le petit-déjeuner et il faut décrocher les voyageurs des rideaux.",
                "电弹菇有一套小火车模型。他给车站上色，检查时刻表，每次列车经过都挥手。一切运行得很好，除非他太兴奋。那时快车会在早饭前跑完六圈，乘客得从窗帘上一个个取下来。"),
            ["Sauerkraut-pult"] = ("Grandma left him a recipe in beautiful handwriting. Grandpa left him a gas mask with a cracked lens. He treasures both. Every Sunday, he opens the jar and the whole neighborhood remembers why Grandpa stopped attending lunch.",
                "Mamie lui a laissé une recette écrite de sa plus belle plume. Papi, un masque à gaz avec un verre fêlé. Lance-choucroute tient beaucoup aux deux. Chaque dimanche, il ouvre le bocal et tout le quartier se rappelle pourquoi papi ne venait plus déjeuner.",
                "奶奶留下了一张字迹漂亮的食谱，爷爷留下了一副镜片裂开的防毒面具。酸菜投手都很珍惜。每到周日，他打开罐子，整条街就想起爷爷为什么不来吃午饭了。"),
            ["Saw-my-pot"] = ("Saw-my-pot is learning ballroom dancing. His teacher says he's light on his feet, which is encouraging for a flower pot. Finding a partner has been harder. He's hung up a notice promising to go slowly and bring spare shoes. Wall-nut has signed up. He doesn't wear shoes.",
                "Pot-scie apprend la danse de salon. Son professeur le trouve léger sur ses pieds, ce qui est encourageant pour un pot de fleurs. Trouver un partenaire est plus difficile. Il a affiché une annonce : promet d'y aller doucement et fournit des chaussures de rechange. Noix s'est inscrit. Il n'en porte pas.",
                "锯齿花盆正在学交际舞。老师说他脚步轻盈，对一个花盆来说很受鼓舞。找舞伴就难了。他贴出告示：保证慢慢跳，还提供备用鞋。坚果报了名。他不穿鞋。"),
            ["Vortex Pot"] = ("A gardener dropped a pebble into him and waited for the sound. Nothing. The next day, the pebble was back on the shelf, cold and neatly polished. Vortex Pot won't discuss where it went.",
                "Un jardinier a laissé tomber un caillou dedans et attendu le bruit. Rien. Le lendemain, le caillou était revenu sur l'étagère, glacé et parfaitement poli. Pot Vortex refuse de raconter où il est passé.",
                "园丁往涡旋花盆里扔了一颗石子，等着听响。没有声音。第二天，石子回到了架子上，冰凉，磨得光滑。他不肯说石子去了哪里。"),
            ["Magnet-o-pea"] = ("Magnet-o-pea collects teaspoons, but only ones with a story. This came from a wedding; that one stirred the mayor's tea. He labels them carefully. The bent one at the back has no label. He says he's still deciding what to write. The Mayor would rather he didn't.",
                "Pisto-aimant collectionne les petites cuillères, mais seulement celles qui ont une histoire. Celle-ci vient d'un mariage ; celle-là a remué le thé du maire. Il les étiquette soigneusement. La cuillère tordue au fond n'a pas d'étiquette. Il cherche encore quoi écrire. Le maire préférerait qu'il ne trouve pas.",
                "磁力豌豆收集茶匙，只收有故事的。这把来自婚礼，那把搅过市长的茶。他仔细贴上标签。最里面那把弯了的还没有标签，他说没想好写什么。市长希望他一直想不好。"),
            ["Ceasarweed"] = ("Ceasarweed insists you try a bite before adding salt. Then she asks what you thought of the dressing, the croutons and the balance of flavours. \"Be honest. I can take it.\" She's written every answer in a little book. Some names are underlined. Yours, for instance.",
                "Ortie de César insiste pour que vous goûtiez avant de saler. Ensuite, elle veut votre avis sur la sauce, les croûtons et l'équilibre des saveurs. « Sois honnête. Je peux l'entendre. » Elle note toutes les réponses dans un petit carnet. Certains noms sont soulignés. Le vôtre, par exemple.",
                "凯撒草坚持让你先尝再撒盐，然后问你酱汁、面包丁和口味搭配如何。“实话实说，我听得进去。”她把所有回答都记在小本子里，有些名字画了下划线，比如你的。"),
            ["Solar Firnace"] = ("\"Leave the door open. You're letting the cold stay in.\" Solar Firnace has his own way of looking at winter. He keeps a chair for visitors, an old kettle and a jar of biscuits that never seems to empty. You can stay until the tea is finished. He'll just put another kettle on.",
                "« Laisse la porte ouverte. Tu empêches le froid de sortir. » Four Solaire a sa propre façon de voir l'hiver. Il garde une chaise pour les visiteurs, une vieille bouilloire et une boîte de biscuits qui ne semble jamais se vider. On peut rester le temps de finir le thé. Il en remettra simplement à chauffer.",
                "“门开着吧，不然冷气出不去。”太阳熔炉看待冬天有自己的办法。他备着一把客人用的椅子、一只旧水壶，还有一盒好像吃不完的饼干。你可以喝完茶再走。他只会再烧一壶。")
        };
        internal static string Get(string name, PlantsPlusLanguage language, string fallback)
        {
            if (!Texts.TryGetValue(name, out var text)) return fallback;
            return language switch
            {
                PlantsPlusLanguage.French => text.Fr,
                PlantsPlusLanguage.Chinese => text.Zh,
                _ => text.En
            };
        }
    }
}
